-- Generated by scripts/generate-seed.mjs — deterministic fictional demo data. Do not edit by hand.
-- Prerequisite: at least one user exists in auth.users (see README → Demo account).
-- Re-running this file RESETS demo data (candidates, jobs, applications, notes, activity, analyses).
begin;
set local app.seeding = 'on';

do $$ begin
  if not exists (select 1 from public.profiles) then
    raise exception 'No users found. Create the demo user first (npm run demo:user), then run this seed.';
  end if;
  perform set_config('app.owner', (select id::text from public.profiles order by created_at limit 1), true);
end $$;

delete from public.candidates;
delete from public.jobs;

